S = "Hakeem Force Academy"
QS = [
(S, "Saudi riyal is the currency of which country?", ["Saudi Arabia", "Qatar", "Oman", "Kuwait"], 0, "The riyal is the official currency of Saudi Arabia, issued by the Saudi Central Bank.", "Qatar and Oman also use a currency called riyal, but the Saudi riyal belongs to Saudi Arabia.", [4556]),
(S, "On which side of Pakistan does the Arabian Sea lie?", ["North", "West", "East", "South"], 3, "Pakistan's coastline of about 1,046 km runs along the Arabian Sea in the south, in Sindh and Balochistan.", "Iran and Afghanistan lie to the west, China to the north-east and India to the east.", [2586, 2922, 2925, 264]),
(S, "What is the approximate total area of Pakistan?", ["796,095 square kilometres", "881,913 square kilometres", "647,500 square kilometres", "1,000,000 square kilometres"], 0, "Pakistan covers about 796,095 square kilometres, the 33rd largest country by area.", "Balochistan is the largest province, covering about 44 percent of the country.", [3497]),
(S, "The Rann of Kutch is a marshy region lying between Sindh (Pakistan) and which Indian state?", ["Rajasthan", "Punjab", "Gujarat", "Maharashtra"], 2, "The Rann of Kutch is a large salt marsh between the Sindh province of Pakistan and the Indian state of Gujarat.", "A 1965 border dispute over the Rann was settled by an international tribunal in 1968.", [1825]),
(S, "If 6 is the arithmetic mean between 4 and B, what is the value of B?", ["6", "7", "8", "10"], 2, "Mean = (4 + B) / 2 = 6, so 4 + B = 12 and B = 8.", "The arithmetic mean of two numbers lies exactly midway between them.", [2333]),
(S, "What is the arithmetic mean of 18 and 36?", ["24", "27", "30", "54"], 1, "Mean = (18 + 36) / 2 = 54 / 2 = 27.", "The arithmetic mean is the sum of the values divided by their number.", [3499]),
(S, "What is the arithmetic mean of (y + 3) and (y - 2)?", ["y + 1", "y + 0.5", "y - 0.5", "2y + 1"], 1, "Sum = (y + 3) + (y - 2) = 2y + 1; dividing by 2 gives y + 0.5.", "Check with y = 1: the numbers are 4 and -1, whose mean is 1.5, which equals 1 + 0.5.", [3500]),
(S, "Around which body does the Earth revolve?", ["Moon", "Sun", "Mars", "Jupiter"], 1, "The Earth orbits the Sun, completing one revolution in about 365.25 days.", "The Moon revolves around the Earth, not the Sun directly.", [774]),
(S, "What is the circling (going around) of the Kaaba during Hajj and Umrah called?", ["Sa'i", "Tawaf", "Wuquf", "Ramy"], 1, "Tawaf is the act of walking seven times around the Kaaba in an anticlockwise direction.", "Tawaf begins and ends at the Black Stone (Hajr-e-Aswad).", [1068, 3628]),
(S, "What is the walking seven times between the hills of Safa and Marwa during Hajj called?", ["Tawaf", "Ramy", "Sa'i", "Wuquf"], 2, "Sa'i is the ritual walk between Safa and Marwa, commemorating Hazrat Hajra's search for water for Ismail (AS).", "The Zamzam well appeared near the Kaaba after this search.", [3835]),
(S, "In the word MANAGEMENT, arranged alphabetically, which letter is second last?", ["M", "G", "N", "T"], 2, "Alphabetical order is A A E E G M M N N T. The last letter is T and the second last is N.", "MANAGEMENT has 10 letters, with A, E, M and N each appearing twice.", [2514]),
(S, "If the letters of the word MANAGEMENT are arranged alphabetically, which letter is third last?", ["M", "N", "G", "T"], 1, "Alphabetical order is A A E E G M M N N T. From the end: T, N, N, so the third last is N.", "The letters N appear twice, in the 8th and 9th places.", [4187]),
(S, "Boxing is called the noble art of what?", ["Self-defence", "Wrestling", "Swordsmanship", "Archery"], 0, "Boxing has long been called the noble art of self-defence.", "Modern boxing rules are based on the Marquess of Queensberry rules of 1867.", [1841]),
(S, "Which Article of the 1973 Constitution of Pakistan declares Islam as the State religion?", ["Article 1", "Article 2", "Article 3", "Article 8"], 1, "Article 2 states that Islam shall be the State religion of Pakistan.", "Article 1 names the country the Islamic Republic of Pakistan.", [2523, 4426]),
(S, "How many articles does the 1973 Constitution of Pakistan have?", ["234", "250", "280", "300"], 2, "The 1973 Constitution, Pakistan's third constitution, contains 280 articles.", "It has 12 parts and 7 schedules and was enforced on 14 August 1973.", [1281, 76, 4008]),
(S, "How many articles did the 1956 Constitution of Pakistan have?", ["234", "250", "280", "205"], 0, "The 1956 Constitution, Pakistan's first constitution, had 234 articles.", "It was enforced on 23 March 1956 and abrogated in October 1958.", [2110, 84]),
(S, "How many articles did the 1962 Constitution of Pakistan have?", ["234", "250", "280", "256"], 1, "The 1962 Constitution given by Ayub Khan had 250 articles.", "It was suspended when martial law was imposed in 1969.", [836, 4009]),
(S, "Bashar al-Assad was the president of which country?", ["Iraq", "Syria", "Lebanon", "Jordan"], 1, "Bashar al-Assad ruled Syria from 2000 until his government fell in December 2024.", "He succeeded his father Hafez al-Assad, who ruled Syria from 1971 to 2000.", [1817]),
(S, "Which animal was with the Ashab-e-Kahf (Companions of the Cave)?", ["Dog", "Horse", "Camel", "Sheep"], 0, "The Quran in Surah Al-Kahf mentions that their dog lay at the entrance of the cave with outstretched paws.", "The dog is traditionally named Qitmir.", [4418, 644]),
(S, "In which part of Asia is India located?", ["East Asia", "Central Asia", "South Asia", "West Asia"], 2, "India lies in South Asia, forming most of the Indian subcontinent.", "SAARC was formed in 1985 by the countries of South Asia.", [939]),
(S, "Aslam was 28 years old in 1945. How old will he be in 1965?", ["38", "45", "48", "50"], 2, "From 1945 to 1965 is 20 years, so his age is 28 + 20 = 48.", "Age problems come down to adding the difference in years.", [776]),
(S, "In which year was Benazir Bhutto assassinated?", ["2005", "2006", "2007", "2008"], 2, "Benazir Bhutto was assassinated on 27 December 2007 in Rawalpindi after an election rally.", "She was the first woman Prime Minister of a Muslim country.", [2721]),
(S, "According to the 1973 Constitution, what is the term of the National Assembly and the Provincial Assemblies?", ["3 years", "4 years", "5 years", "6 years"], 2, "Unless dissolved earlier, the National and Provincial Assemblies serve a term of five years from their first meeting.", "A Senator's term is six years, with half retiring every three years.", [1683, 1194]),
(S, "Who promulgates ordinances in Pakistan when the National Assembly is not in session?", ["Prime Minister", "Chief Justice", "President", "Speaker"], 2, "Under Article 89 of the Constitution, the President may promulgate an ordinance when Parliament is not in session.", "An ordinance must be laid before Parliament and lapses after 120 days unless extended or approved.", [5412]),
(S, "What was the code name of Pakistan's first nuclear tests of 28 May 1998?", ["Chagai-I", "Operation Smiling Buddha", "Shakti", "Zarb-e-Azb"], 0, "Pakistan's tests of 28 May 1998 at Chagai in Balochistan were code-named Chagai-I.", "India's 1974 test was Smiling Buddha and its 1998 tests were Shakti; Pakistan's second test on 30 May 1998 was Chagai-II.", [4123]),
(S, "What will be the third letter when the word AUGMENTED is arranged alphabetically?", ["D", "E", "G", "A"], 1, "Alphabetical order is A D E E G M N T U, so the third letter is E.", "AUGMENTED has 9 letters, with E appearing twice.", [3996, 4188]),
(S, "What is the currency of Australia?", ["Australian dollar", "Australian pound", "Rand", "New Zealand dollar"], 0, "Australia uses the Australian dollar (AUD).", "Australia used the Australian pound until decimal currency was introduced in 1966.", [3561]),
(S, "Who is the Prime Minister of Australia (as of 2026)?", ["Scott Morrison", "Anthony Albanese", "Malcolm Turnbull", "Peter Dutton"], 1, "Anthony Albanese of the Labor Party has been Prime Minister since May 2022.", "His predecessor Scott Morrison served from 2018 to 2022.", [5142]),
(S, "Sahih Bukhari is regarded as the most authentic book of hadith after which book?", ["Sahih Muslim", "Sunan Abu Dawud", "Holy Quran", "Muwatta Imam Malik"], 2, "Muslims regard the Holy Quran as the most authentic book, followed in authenticity by Sahih Bukhari among the hadith books.", "Imam Bukhari compiled his collection over about 16 years.", [1011]),
(S, "Who is the author of the book India of My Dreams?", ["Jawaharlal Nehru", "Mahatma Gandhi", "Rabindranath Tagore", "Abul Kalam Azad"], 1, "India of My Dreams is a collection of the writings of Mahatma Gandhi on his vision for India, compiled by R. K. Prabhu.", "Gandhi's autobiography is titled The Story of My Experiments with Truth.", [5105]),
(S, "Who is the author of the book In the Line of Fire?", ["Pervez Musharraf", "Benazir Bhutto", "Nawaz Sharif", "Zulfikar Ali Bhutto"], 0, "In the Line of Fire (2006) is the memoir of General Pervez Musharraf.", "It was published when Musharraf was President of Pakistan.", [5113]),
(S, "Who is the author of the book Mein Kampf?", ["Benito Mussolini", "Joseph Stalin", "Winston Churchill", "Adolf Hitler"], 3, "Mein Kampf (My Struggle) was written by Adolf Hitler, partly while he was in prison in 1924.", "It was published in two volumes in 1925 and 1926.", [5114]),
]
